#include <stdio.h>

int main(void) {
    int bowls[5] = {{v0}, {v1}, {v2}, {v3}, {v4}};

    int total_size = (int)sizeof(bowls);
    int one_size = (int)sizeof(bowls[0]);
    int count = total_size / one_size;

    printf("这排碗一共占 %d 格\n", total_size);
    printf("一只碗占 %d 格\n", one_size);
    printf("这排碗有 %d 只\n", count);

    for (int i = 0; i < count; i++) {
        printf("第 %d 只：%d 条小鱼干\n", i, bowls[i]);
    }

    return 0;
}
